# per-pair: m2/m3 positions, bg, shortest-path lengths, actual added sets
def f(k):
    gi,go=pairs[k]
    h,w=len(gi),len(gi[0])
    bgc=collections.Counter(x for r in gi for x in r).most_common(1)[0][0]
    m2=[(i,j) for i in range(h) for j in range(w) if gi[i][j]==2]
    m3=[(i,j) for i in range(h) for j in range(w) if gi[i][j]==3]
    def nbs(u): return [(u[0]+di,u[1]+dj) for di,dj in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=u[0]+di<h and 0<=u[1]+dj<w]
    src={(p,q) for c in m2 for (p,q) in nbs(c)}
    tgt={(p,q) for c in m3 for (p,q) in nbs(c)}
    d={s:0 for s in src}; par={}; dq=deque(src)
    while dq:
        u=dq.popleft()
        for v in nbs(u):
            if v not in d: d[v]=d[u]+1; par[v]=u; dq.append(v)
    L=min(d[t] for t in tgt if t in d)
    act=set((i,j) for i in range(h) for j in range(w) if go[i][j]!=bgc and gi[i][j]==bgc)
    info=[]
    for e in tgt:
        if d[e]!=L: continue
        n=e; p=[]
        while True:
            p.append(n); n=par.get(n,None)
            if n in src or n is None: break
        if n not in src: continue
        info.append((tuple(sorted(set(p)),set(p)==act)))
    return L,act,tuple(m2),tuple(m3),info
for k in sorted(pairs):
    L,act,m2,m3,res=f(k)
    print('pair',k,'shortest L=',L,'actual size',len(act),'marker2',m2,'marker3',m3)
    for p,eq in res[:2]:
        print('   path len',len(p),'match actual:',eq)

