def comps(grid,val=None):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if (val is None or grid[r][c]==val) and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<h and 0<=b<w and not seen[a][b] and (grid[a][b]==val if val is not None else True):
                                seen[a][b]=True; st.append((a,b))
                out.append(cells)
    return out
